const CHART_FRAMES:{key:ChartPreset;title:string;max:number}[]=[{key:'today',title:'Today',max:24},{key:'week',title:'Past week',max:7},{key:'month',title:'Past month',max:30},{key:'year',title:'Past year',max:365},{key:'custom',title:'Custom range',max:730}];
const CHART_DEFAULT_MODES:Record<ChartPreset,ChartBarsMode[]>={today:['hour','day','custom'],week:['day','week','custom'],month:['day','week','month','custom'],year:['day','week','month','year','custom'],custom:['hour','day','week','month','year','custom']};
const CHART_FRAME_SPANS:Record<ChartPreset,number>={today:1,week:7,month:30,year:365,custom:30};
const weekStartIndex=(value:string):WeekStartsOn=>value==='monday'?1:0;
const previewBarCount=(frame:ChartPreset,mode:ChartBarsMode,weekStartsOn:WeekStartsOn)=>{if(frame==='custom'||mode==='custom')return 0;if(mode==='week'&&(frame==='month'||frame==='year')){const now=Date.now();const range=resolveRange(frame,'','',now);const aligned=alignWeekRange(range.startMs,range.endMs,weekStartsOn,now);let count=0;let cursor=aligned.startMs;while(cursor<aligned.endMs&&count<200){count+=1;cursor=new Date(cursor).setDate(new Date(cursor).getDate()+7)}return Math.max(1,count)}return unitBarsForSpan(mode,CHART_FRAME_SPANS[frame])};
const compareCategories=(a:Category,b:Category)=>a.name.localeCompare(b.name,undefined,{sensitivity:'base'});
const readStore=():Store=>{try{const raw=localStorage.getItem('focus-tracker-v1');if(raw){const parsed=JSON.parse(raw);const tasks=(Array.isArray(parsed.tasks)?parsed.tasks:[]).map((value:Partial<Task>)=>{const startDate=value.startDate||today();const recurrence:Recurrence=['daily','weekdays','weekly','monthly'].includes(value.recurrence as Recurrence)?value.recurrence as Recurrence:'weekly';return {...value,startDate,endDate:value.endDate||'',recurring:Boolean(value.recurring),recurrence,completed:Boolean(value.completed),weeklyDays:Array.isArray(value.weeklyDays)?value.weeklyDays:value.recurring&&recurrence==='weekly'?[weekdayIndex(startDate)]:[],monthlyDays:Array.isArray(value.monthlyDays)?value.monthlyDays:value.recurring&&recurrence==='monthly'?[Number(startDate.slice(-2))]:[],lastCompletedDate:value.lastCompletedDate||undefined} as Task});const storedCategories=Array.isArray(parsed.categories)?parsed.categories as Category[]:[...defaults.categories];const categories=[...storedCategories];const permanentErrand=categories.find(c=>c?.id==='cat-errands');if(!permanentErrand)categories.push({id:'cat-errands',name:'Errands',color:'#d78b53'});else if(permanentErrand.name!=='Errands')permanentErrand.name='Errands';const rawSettings=((parsed as {settings?:Partial<Settings>}).settings??{}) as Partial<Settings> & {googleAutoSync?:boolean};const {googleAutoSync:legacyAuto,...restRawSettings}=rawSettings;const mergedSettings:Settings={...defaults.settings,...restRawSettings};if(rawSettings.googleSyncFrequency===undefined)mergedSettings.googleSyncFrequency=legacyAuto?'change':'off';if(mergedSettings.weekStartsOn!=='sunday'&&mergedSettings.weekStartsOn!=='monday')mergedSettings.weekStartsOn='sunday';return {...defaults,...parsed,categories,tasks:normalizePriorities(tasks),settings:mergedSettings}}}catch{}return defaults};
const uid=()=>`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
const dateLabel=(d:string)=>d?new Date(`${d}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'No date';
const durationLabel=(s:number)=>{const h=Math.floor(s/3600),m=Math.floor(s%3600/60);return h?`${h}h ${m}m`:m?`${m}m`:`${s}s`};
const clockLabel=(s:number)=>`${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
const maxCountdownSeconds=240*60;
const pendingRunKey='focus-tracker-pending-run';
type PendingRun={mode:'stopwatch'|'timer';total:number;base:number;runStarted:number;elapsed:number;startedAt:string;categoryId:string;taskId:string;note:string;savedAt:number};
type ClockParts={h:string;m:string;s:string};
const emptyClockParts:ClockParts={h:'00',m:'25',s:'00'};
const digitsOnly=(value:string)=>value.replace(/\D/g,'').slice(-2);
const clockPart=(value:string,max:number)=>String(Math.min(max,Number(digitsOnly(value)||'0'))).padStart(2,'0');
const secondsToParts=(total:number):ClockParts=>{const safe=Math.max(0,Math.min(maxCountdownSeconds,total));return {h:String(Math.floor(safe/3600)).padStart(2,'0'),m:String(Math.floor(safe%3600/60)).padStart(2,'0'),s:String(safe%60).padStart(2,'0')}};
const normalizeParts=(parts:ClockParts):ClockParts=>{const h=clockPart(parts.h,4);let m=clockPart(parts.m,59);let s=clockPart(parts.s,59);if(Number(h)>=4){m='00';s='00'}const total=Math.min(maxCountdownSeconds,Number(h)*3600+Number(m)*60+Number(s));return secondsToParts(total)};
const durationToParts=(total:number):ClockParts=>{const safe=Math.max(0,Math.floor(total));return {h:String(Math.floor(safe/3600)).padStart(2,'0'),m:String(Math.floor(safe%3600/60)).padStart(2,'0'),s:String(safe%60).padStart(2,'0')}};
const normalizeDurationParts=(parts:ClockParts):ClockParts=>({h:String(Math.min(99,Number(digitsOnly(parts.h).slice(-3)||'0'))).padStart(2,'0'),m:clockPart(parts.m,59),s:clockPart(parts.s,59)});

function PriorityField({value,max,onCommit,testId}:{value:number;max:number;onCommit:(next:number)=>void;testId:string}){
  const [draft,setDraft]=useState(String(value));
  useEffect(()=>{setDraft(String(value))},[value]);
  const commit=(raw:string)=>{const parsed=Number(raw);if(!raw.trim()||!Number.isInteger(parsed)){setDraft(String(value));return}const next=Math.min(max,Math.max(1,parsed));setDraft(String(next));if(next!==value)onCommit(next)};
  return <input className="input priority-input" type="text" inputMode="numeric" aria-label={`Priority, 1 through ${max}, and tasks can share a number`} title="Priority from 1 to the number of tasks in this list, and tasks can share a number" value={draft} onChange={event=>setDraft(event.target.value.replace(/\D/g,'').slice(0,4))} onBlur={event=>commit(event.currentTarget.value)} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();commit(event.currentTarget.value)}}} data-testid={testId}/>;
}

